echo "== recall marker (new process)"; gbrain recall gbrain-install-check --json | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const j=JSON.parse(s);console.log((j.facts||[]).map(f=>f.id+" | "+f.fact).join("\n")||s.slice(0,600))})'; echo exit=${PIPESTATUS[0]}

export PATH="$HOME/.bun/bin:$PATH"; mkdir -p /tmp/gbrain-scripts; cat > /tmp/gbrain-scripts/mcp.mjs <<'EOF'
import { spawn } from "node:child_process";
const p = spawn("/harness-state/.gbrain/hook-launcher/gbrain-hook", ["/harness-state/.bun/bin/gbrain","serve","--surface","starter","--advertise","verbs"], {stdio:["pipe","pipe","inherit"]});
let buf=""; const waiters={};
p.stdout.on("data",d=>{buf+=d; let i; while((i=buf.indexOf("\n"))>=0){const l=buf.slice(0,i);buf=buf.slice(i+1); try{const m=JSON.parse(l); if(m.id&&waiters[m.id]) waiters[m.id](m);}catch{}}});
